const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laSerena = ee.Geometry.Point([-71.3, -29.9]);

  // Year-to-date 2024 (Jan 1 - July 7, 2024)
  const ytd2024Start = '2024-01-01';
  const ytd2024End = '2024-07-07';

  // Historical period: Same days (Jan 1 - July 7) for years 1990-2020
  const historicalYears = ee.List.sequence(1990, 2020);

  // 2. Data Acquisition for 2024 YTD
  const chirps2024 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(ytd2024Start, ytd2024End)
    .filterBounds(laSerena);

  const count2024 = chirps2024.size().getInfo();
  console.log('2024 YTD Images:', count2024);

  if (count2024 === 0) {
    console.log('No data for 2024 YTD period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Calculate 2024 YTD rainfall
  const rainfall2024 = chirps2024.select('precipitation').sum();

  const stats2024 = rainfall2024.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: laSerena,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const ytdRainfall2024 = stats2024.precipitation;

  if (ytdRainfall2024 === null || ytdRainfall2024 === undefined) {
    console.log('Failed to calculate 2024 YTD rainfall.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log('2024 YTD Rainfall (mm):', ytdRainfall2024.toFixed(2));

  // 4. Calculate historical average (1990-2020) for same period
  const historicalRainfall = historicalYears.map(function(year) {
    const yearInt = ee.Number(year).toInt();
    const startDate = ee.Date.fromYMD(yearInt, 1, 1);
    const endDate = ee.Date.fromYMD(yearInt, 7, 7);

    const yearlyCol = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(startDate, endDate)
      .filterBounds(laSerena);

    const yearlySum = yearlyCol.select('precipitation').sum();

    return yearlySum.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: laSerena,
      scale: 5000,
      maxPixels: 1e9
    }).get('precipitation');
  });

  const historicalList = historicalRainfall.getInfo();
  const validHistorical = historicalList.filter(val => val !== null && val !== undefined);

  if (validHistorical.length === 0) {
    console.log('No valid historical data found.');
    console.log('<answer>C1</answer>');
    return;
  }

  const historicalAvg = validHistorical.reduce((a, b) => a + b, 0) / validHistorical.length;

  console.log('Historical Years with Data:', validHistorical.length);
  console.log('Historical Avg Rainfall (mm):', historicalAvg.toFixed(2));

  // 5. Validation & Final Answer
  if (isNaN(historicalAvg) || historicalAvg < 0) {
    console.log('Invalid historical average.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log('Comparison: 2024 YTD (' + ytdRainfall2024.toFixed(2) + ') vs Historical (' + historicalAvg.toFixed(2) + ')');

  if (ytdRainfall2024 < historicalAvg) {
    console.log('2024 YTD rainfall is LOWER than historical average.');
    console.log('<answer>A</answer>');
  } else {
    console.log('2024 YTD rainfall is NOT lower than historical average.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
